# BM25 와 하이브리드(RRF) — 키워드가 반드시 들어간 청크를 위로
import math, re
docs = ["Huggy likes to work downstairs", "Where is Paris located?",
        "he was in a cuddly mood", "Cuddly spends most days surrounded by books"]
STOP = {"where", "is", "a", "in", "to", "by", "he", "was"}
def tok(s, stop=True):
    return [w for w in re.findall(r"[a-z]+", s.lower()) if not (stop and w in STOP)]
def bm25_all(q, stop, k1=1.2, b=0.75):
    D = [tok(d, stop) for d in docs]; N = len(D); avgdl = sum(map(len, D)) / N
    def idf(t):
        n = sum(t in d for d in D)
        return math.log((N - n + 0.5) / (n + 0.5) + 1)
    return [sum(idf(t) * d.count(t) * (k1 + 1) /
                (d.count(t) + k1 * (1 - b + b * len(d) / avgdl)) for t in tok(q, stop)) for d in D]
q = "Where is Cuddly?"
for stop in (False, True):
    s = bm25_all(q, stop)
    print("불용어 제거" if stop else "그대로", [round(x, 3) for x in s])
bm = bm25_all(q, True)
bm_list = [i for i in sorted(range(4), key=lambda i: -bm[i]) if bm[i] > 0]   # 점수 0 은 못 찾은 것
sem_list = [0, 3, 1, 2]                     # 코사인 순위(앞 장의 코드 결과)
rrf = {i: sum(1 / (60 + L.index(i) + 1) for L in (sem_list, bm_list) if i in L) for i in range(4)}
for i in sorted(rrf, key=lambda i: -rrf[i]):
    print(f"RRF {rrf[i]:.5f}  {docs[i]}")

