# MCP 흉내: JSON-RPC 2.0 으로 tools/list → tools/call (실제 SDK 가 아니라 메시지 모양만)
import json
class BookServer:                                    # '책 제공자' MCP 서버
    tools = {"find_title": {"description": "Find a book by title",
                            "inputSchema": {"type": "object", "properties": {"title": {"type": "string"}},
                                            "required": ["title"]}}}
    books = {"leaves of grass": {"author": "Walt Whitman", "genre": "poetry"}}
    def handle(self, raw):
        req = json.loads(raw)
        if req["method"] == "tools/list":
            res = {"tools": [{"name": n, **t} for n, t in self.tools.items()]}
        elif req["method"] == "tools/call":
            title = req["params"]["arguments"]["title"].lower()
            res = {"content": [{"type": "text", "text": json.dumps(self.books.get(title, {}))}]}
        else:
            return json.dumps({"jsonrpc": "2.0", "id": req["id"], "error": {"code": -32601, "message": "no method"}})
        return json.dumps({"jsonrpc": "2.0", "id": req["id"], "result": res})
server = BookServer()                                # 호스트 안의 클라이언트가 서버 하나와 1:1 로 붙는다
print(server.handle(json.dumps({"jsonrpc": "2.0", "id": 1, "method": "tools/list"})))
print(server.handle(json.dumps({"jsonrpc": "2.0", "id": 2, "method": "tools/call",
      "params": {"name": "find_title", "arguments": {"title": "Leaves of Grass"}}})))
for n_llm, n_tool in [(3, 3), (10, 50)]:
    print(f"LLM {n_llm} × 도구 {n_tool}: 맞춤 연결 {n_llm * n_tool}개 → MCP {n_llm + n_tool}개")

# ReAct 고리(관찰→계획→행동)와 회차마다 불어나는 입력 토큰
room = {"temp_f": 65}
def get_current_room_temperature(): return {"temp_f": room["temp_f"]}
def increase_temperature(value): room["temp_f"] += value; return {"temp_f": room["temp_f"]}
TOOLS = {f.__name__: f for f in (get_current_room_temperature, increase_temperature)}
def llm(history):                     # 진짜 LLM 대신 규칙으로 '생각'하는 정책
    last = history[-1]
    if last["role"] == "user": return ("get_current_room_temperature", {})
    t = last["content"]["temp_f"]
    if t < 70: return ("increase_temperature", {"value": 70 - t})
    return ("final", f"The thermostat is now set to {t}F.")
T0, STEP_OUT, OBS = 2_000, 80, 200    # 시스템+도구 설명, 회차당 출력, 관찰 토큰(어림)
history, used_in = [{"role": "user", "content": "My teddy bear is cold."}], 0
for step in range(1, 11):             # 최대 회차를 꼭 둔다
    used_in += T0 + 20 + (step - 1) * (STEP_OUT + OBS)   # 매 회차 전체 기록을 다시 보낸다
    name, arg = llm(history)
    print(step, name, arg)
    if name == "final": break
    history.append({"role": "tool", "content": TOOLS[name](**arg)})
print("입력 토큰 합:", used_in, "| 출력:", step * STEP_OUT,
      f"| 비용 ${used_in * 1.25e-6 + step * STEP_OUT * 10e-6:.4f}")
n = 20; print("20회차였다면 입력:", n * (T0 + 20) + (STEP_OUT + OBS) * n * (n - 1) // 2)
